import { createTeamsFromParticipantAttributes } from '../../../mutate/participants/createTeamsFromAttributes.mjs';
import { addParticipants } from '../../../mutate/participants/addParticipants.mjs';
import { getParticipantId } from '../../../functions/global/extractors.mjs';
import { generateParticipants } from './generateParticipants.mjs';
import { getParticipantsCount } from './getParticipantsCount.mjs';
import { generateRange } from '../../../tools/arrays.mjs';
import { INDIVIDUAL, TEAM } from '../../../constants/participantConstants.mjs';
import { COMPETITOR } from '../../../constants/participantRoleValues.mjs';
import { genParticipantId } from './genParticipantId.mjs';
import { SUCCESS } from '../../../constants/resultConstants.mjs';

function addTournamentParticipants({ participantsProfile, tournamentRecord, eventProfiles, drawProfiles, startDate, random, uuids, }) {
    if (participantsProfile?.participantsCount === 0)
        return { addedCount: 0, ...SUCCESS };
    const { participantsCount, participantType, largestTeamDraw, largestTeamSize, gendersCount } = getParticipantsCount({
        participantsProfile,
        eventProfiles,
        drawProfiles,
    });
    const teamKey = participantsProfile?.teamKey;
    const idPool = participantsProfile?.uuids ?? uuids;
    const generated = generateParticipants({
        consideredDate: startDate,
        ...participantsProfile,
        participantsCount,
        participantType,
        uuids: idPool,
        gendersCount,
        random,
    });
    if (generated.error)
        return generated;
    const participants = generated.participants;
    let addedCount = 0;
    let result = addParticipants({ tournamentRecord, participants });
    if (result.error)
        return result;
    addedCount += result.addedCount;
    if (teamKey) {
        const result = createTeamsFromParticipantAttributes({
            tournamentRecord,
            ...teamKey,
        });
        if (result.error)
            return result;
    }
    const allIndividualParticipantIds = participants
        .filter(({ participantType }) => participantType === INDIVIDUAL)
        .map(getParticipantId);
    const idPrefix = participantsProfile?.idPrefix ? `${TEAM}-${participantsProfile.idPrefix}` : undefined;
    const teamParticipants = generateRange(0, largestTeamDraw).map((teamIndex) => {
        const individualParticipantIds = allIndividualParticipantIds.slice(teamIndex * largestTeamSize, (teamIndex + 1) * largestTeamSize);
        const participantId = genParticipantId({
            index: teamIndex,
            participantType,
            uuids: idPool,
            idPrefix,
            random,
        });
        return {
            participantName: `Team ${teamIndex + 1}`,
            participantRole: COMPETITOR,
            individualParticipantIds,
            participantType: TEAM,
            participantId,
        };
    });
    result = addParticipants({
        participants: teamParticipants,
        tournamentRecord,
    });
    if (result.error)
        return result;
    addedCount += result.addedCount;
    return { addedCount, ...SUCCESS };
}

export { addTournamentParticipants };
